'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );


// FUNCTIONS //

/**
* Copies elements from one array to another array and replaces all elements within a specified range according to a provided callback function.
*
* @private
* @param {Collection} x - input array
* @param {integer} start - starting index (inclusive)
* @param {integer} end - ending index (exclusive)
* @param {Function} fcn - callback function
* @param {*} thisArg - callback function execution context
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array offset
* @returns {Collection} output array
*
* @example
* function fcn() {
*     return 5;
* }
*
* var x = [ 1, 2, 3, 4 ];
*
* var out = [ 0, 0, 0, 0 ];
* var arr = indexed( x, 1, 3, fcn, {}, out, 1, 0 );
* // returns [ 1, 5, 5, 4 ]
*
* var bool = ( arr === out );
* // returns true
*/
function indexed( x, start, end, fcn, thisArg, out, stride, offset ) {
	var io;
	var i;

	io = offset;
	for ( i = 0; i < x.length; i++ ) {
		if ( i >= start && i < end ) {
			out[ io ] = fcn.call( thisArg, x[ i ], i, x );
		} else {
			out[ io ] = x[ i ];
		}
		io += stride;
	}
	return out;
}

/**
* Copies elements from one accessor array to another accessor array and replaces all elements within a specified range according to a provided callback function.
*
* @private
* @param {Object} x - input array object
* @param {integer} start - starting index (inclusive)
* @param {integer} end - ending index (exclusive)
* @param {Function} fcn - callback function
* @param {*} thisArg - callback function execution context
* @param {Object} out - output array object
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array offset
* @returns {Collection} output array
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* function fcn() {
*     return 5;
* }
*
* var x = toAccessorArray( [ 1, 2, 3, 4 ] );
*
* var out = toAccessorArray( [ 0, 0, 0, 0 ] );
* var arr = accessors( arraylike2object( x ), 1, 3, fcn, {}, arraylike2object( out ), 1, 0 );
*
* var v = arr.get( 1 );
* // returns 5
*/
function accessors( x, start, end, fcn, thisArg, out, stride, offset ) {
	var xdata;
	var odata;
	var xget;
	var oset;
	var io;
	var i;

	xdata = x.data;
	odata = out.data;

	xget = x.accessors[ 0 ];
	oset = out.accessors[ 1 ];

	io = offset;
	for ( i = 0; i < xdata.length; i++ ) {
		if ( i >= start && i < end ) {
			oset( odata, io, fcn.call( thisArg, xget( xdata, i ), i, xdata ) );
		} else {
			oset( odata, io, xget( xdata, i ) );
		}
		io += stride;
	}
	return odata;
}


// MAIN //

/**
* Copies elements from one array to another array and replaces all elements within a specified range according to a provided callback function.
*
* @param {Collection} x - input array
* @param {integer} start - starting index (inclusive)
* @param {integer} end - ending index (exclusive)
* @param {Function} fcn - callback function
* @param {Collection} out - output array
* @param {integer} stride - output array stride
* @param {NonNegativeInteger} offset - output array offset
* @param {*} [thisArg] - callback function execution context
* @returns {Collection} output array
*
* @example
* function fcn() {
*     return 5;
* }
*
* var x = [ 1, 2, 3, 4 ];
*
* var out = [ 0, 0, 0, 0 ];
* var arr = assign( x, 1, 3, fcn, out, 1, 0 );
* // returns [ 1, 5, 5, 4 ]
*
* var bool = ( arr === out );
* // returns true
*/
function assign( x, start, end, fcn, out, stride, offset, thisArg ) {
	var len;
	var xo;
	var oo;

	len = x.length;
	if ( start < 0 ) {
		start += len;
		if ( start < 0 ) {
			start = 0;
		}
	}
	if ( end < 0 ) {
		end += len; // if `end` is still negative, that is fine, as `x` will simply be copied without modification
	} else if ( end > len ) {
		end = len;
	}
	xo = arraylike2object( x );
	oo = arraylike2object( out );
	if ( xo.accessorProtocol || oo.accessorProtocol ) {
		accessors( xo, start, end, fcn, thisArg, oo, stride, offset );
		return out;
	}
	indexed( x, start, end, fcn, thisArg, out, stride, offset );
	return out;
}


// EXPORTS //

module.exports = assign;
